const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

let input = [];
rl.on('line', (line) => {
  input.push(line);
});

rl.on('close', () => {
  const N = parseInt(input[0]);
  const a = input.slice(1, N + 1).map(Number);

  if (N === 1 && a[0] === 0) {
    console.log("UP");
    return;
  }
  if (N === 1 && a[0] === 15) {
    console.log("DOWN");
    return;
  }
  if (N === 1 && a[0] !== 0 && a[0] !== 15) {
    console.log(-1);
    return;
  }

  if (a[N - 2] > a[N - 1] && a[N - 1] !== 0) {
    console.log("DOWN");
    return;
  }
  if (a[N - 2] < a[N - 1] && a[N - 1] !== 15) {
    console.log("UP");
    return;
  }
  if (a[N - 1] === 0) {
    console.log("UP");
    return;
  }
  if (a[N - 1] === 15) {
    console.log("DOWN");
    return;
  }
});
```

